-- Original Mystic Wolf artwork, embedded as PNG (no external download).
local wolfImageAsset = ""
do
    local encodedWolf = ""
    local function decodeBase64(value)
        local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        local lookup = {}
        for i=1,#alphabet do lookup[alphabet:sub(i,i)] = i-1 end
        local chunks = {}
        for i=1,#value,4 do
            local a=lookup[value:sub(i,i)] or 0
            local b=lookup[value:sub(i+1,i+1)] or 0
            local c=lookup[value:sub(i+2,i+2)] or 0
            local d=lookup[value:sub(i+3,i+3)] or 0
            local n=a*262144+b*4096+c*64+d
            local bytes=string.char(math.floor(n/65536)%256)
            if value:sub(i+2,i+2)~="=" then bytes=bytes..string.char(math.floor(n/256)%256) end
            if value:sub(i+3,i+3)~="=" then bytes=bytes..string.char(n%256) end
            chunks[#chunks+1]=bytes
            if #chunks%8192==0 then task.wait() end
        end
        return table.concat(chunks)
    end
    local assetLoader = getcustomasset or getsynasset
    if type(assetLoader)=="function" and type(writefile)=="function" then
        local ok,result=pcall(function()
            if type(isfolder)=="function" and type(makefolder)=="function" then
                if not isfolder("Mystic Mods Assets") then makefolder("Mystic Mods Assets") end
            end
            local path="Mystic Mods Assets/mystic_wolf.png"
            writefile(path,decodeBase64(encodedWolf))
            return assetLoader(path)
        end)
        if ok and type(result)=="string" then wolfImageAsset=result end
    end
    if wolfImageAsset=="" then warn("[Mystic Mods] Custom image loading unavailable; using text branding.") end
end

-- Mystic Mods: reference-inspired Roblox interface.
-- Feature controls are UI examples; connect callbacks to your game's code.
local Players=game:GetService("Players")
local UIS=game:GetService("UserInputService")
local Run=game:GetService("RunService")
local Tween=game:GetService("TweenService")
local env=getgenv and getgenv() or _G
if env.MysticReferenceCleanup then env.MysticReferenceCleanup() end
local connections={}
local function listen(signal,fn)
    local c=signal:Connect(fn) table.insert(connections,c) return c
end
local function make(class,props,parent)
    local o=Instance.new(class)
    for k,v in pairs(props) do o[k]=v end
    o.Parent=parent return o
end
local function round(o,r) make("UICorner",{CornerRadius=UDim.new(0,r or 12)},o) end
local purple=Color3.fromRGB(168,92,255)
local bright=Color3.fromRGB(224,181,255)
local muted=Color3.fromRGB(157,149,172)
local white=Color3.fromRGB(241,235,250)
local function text(parent,value,pos,size,fontSize,color)
    return make("TextLabel",{Text=value,Position=pos,Size=size,BackgroundTransparency=1,TextColor3=color or white,Font=Enum.Font.GothamMedium,TextSize=fontSize or 13,TextXAlignment=Enum.TextXAlignment.Left,TextTruncate=Enum.TextTruncate.AtEnd},parent)
end
local parent=Players.LocalPlayer:WaitForChild("PlayerGui")
if gethui then local ok,h=pcall(gethui) if ok and h then parent=h end end
local gui=make("ScreenGui",{Name="MysticModsReference",ResetOnSpawn=false,DisplayOrder=100,ZIndexBehavior=Enum.ZIndexBehavior.Sibling},parent)
local main=make("Frame",{Size=UDim2.fromOffset(680,570),AnchorPoint=Vector2.new(.5,.5),Position=UDim2.fromScale(.5,.5),BackgroundColor3=Color3.fromRGB(17,14,23),BorderSizePixel=0},gui)
round(main,20)
make("UIGradient",{Rotation=70,Color=ColorSequence.new(Color3.fromRGB(33,21,43),Color3.fromRGB(12,12,18))},main)
make("UIStroke",{Color=purple,Thickness=2,Transparency=.3},main)
local inner=make("Frame",{Position=UDim2.fromOffset(5,5),Size=UDim2.new(1,-10,1,-10),BackgroundTransparency=1},main)
round(inner,16) make("UIStroke",{Color=purple,Thickness=1,Transparency=.82},inner)
local scale=make("UIScale",{},main)
local header=make("Frame",{Position=UDim2.fromOffset(0,0),Size=UDim2.new(1,-94,0,78),BackgroundTransparency=1,Active=true},main)
make("ImageLabel",{Position=UDim2.fromOffset(14,5),Size=UDim2.fromOffset(70,70),Image=wolfImageAsset,BackgroundTransparency=1,ScaleType=Enum.ScaleType.Fit},header)
local title=text(header,"MYSTIC MODS",UDim2.fromOffset(96,18),UDim2.fromOffset(250,28),23)
title.Font=Enum.Font.GothamBold
text(header,"MYSTIC WOLF  /  UNIVERSAL UI",UDim2.fromOffset(97,46),UDim2.fromOffset(265,20),10,muted)
local fps=text(main,"FPS --",UDim2.new(1,-218,0,26),UDim2.fromOffset(108,20),11,bright)
local function icon(value,x,fn)
    local b=make("TextButton",{Position=UDim2.new(1,x,0,23),Size=UDim2.fromOffset(28,28),Text=value,TextColor3=muted,TextSize=20,BackgroundTransparency=1,Selectable=true},main)
    listen(b.Activated,fn) return b
end
local reopen=make("TextButton",{Position=UDim2.fromOffset(16,100),Size=UDim2.fromOffset(154,40),Text="MYSTIC MODS",Font=Enum.Font.GothamBold,TextSize=12,TextColor3=bright,BackgroundColor3=Color3.fromRGB(35,24,48),Visible=false,Selectable=true},gui) round(reopen,12)
local function show(value) main.Visible=value reopen.Visible=not value end
icon("-",-78,function() show(false) end)
local cleaned=false
local cleanup
cleanup=function()
    if cleaned then return end cleaned=true
    for _,c in ipairs(connections) do c:Disconnect() end
    gui:Destroy()
    if env.MysticReferenceCleanup==cleanup then env.MysticReferenceCleanup=nil end
end
env.MysticReferenceCleanup=cleanup
icon("x",-43,cleanup)
listen(reopen.Activated,function() show(true) end)
local status=text(main,"Ready · Example controls are not game modifications",UDim2.new(0,22,1,-33),UDim2.new(1,-44,0,18),11,muted)
local function note(value) status.Text=value end
local search=make("TextBox",{Position=UDim2.fromOffset(22,130),Size=UDim2.new(1,-44,0,34),Text="",PlaceholderText="Search controls...",ClearTextOnFocus=false,BackgroundColor3=Color3.fromRGB(31,25,39),TextColor3=white,PlaceholderColor3=muted,Font=Enum.Font.Gotham,TextSize=12,TextXAlignment=Enum.TextXAlignment.Left},main)
round(search,10) make("UIPadding",{PaddingLeft=UDim.new(0,12),PaddingRight=UDim.new(0,12)},search)
local nav=make("Frame",{Position=UDim2.fromOffset(22,84),Size=UDim2.new(1,-44,0,34),BackgroundTransparency=1},main)
make("UIListLayout",{FillDirection=Enum.FillDirection.Horizontal,Padding=UDim.new(0,8)},nav)
local pages,buttons,rows={}, {}, {}
local active="Main"
local function filter()
    local query=search.Text:lower()
    for _,row in ipairs(rows) do row.object.Visible=query=="" or row.name:lower():find(query,1,true)~=nil end
end
local function tab(name)
    local page=make("ScrollingFrame",{Position=UDim2.fromOffset(22,179),Size=UDim2.new(1,-44,1,-229),CanvasSize=UDim2.new(),AutomaticCanvasSize=Enum.AutomaticSize.Y,BackgroundTransparency=1,BorderSizePixel=0,ScrollBarThickness=3,ScrollBarImageColor3=purple,Visible=false},main)
    local left=make("Frame",{Size=UDim2.new(.5,-6,0,0),AutomaticSize=Enum.AutomaticSize.Y,BackgroundTransparency=1},page)
    local right=make("Frame",{Position=UDim2.new(.5,6,0,0),Size=UDim2.new(.5,-6,0,0),AutomaticSize=Enum.AutomaticSize.Y,BackgroundTransparency=1},page)
    for _,column in ipairs({left,right}) do make("UIListLayout",{Padding=UDim.new(0,9),SortOrder=Enum.SortOrder.LayoutOrder},column) make("UIPadding",{PaddingBottom=UDim.new(0,12)},column) end
    pages[name]=page
    local b=make("TextButton",{Size=UDim2.fromOffset(92,34),Text=name,Font=Enum.Font.GothamMedium,TextSize=12,TextColor3=muted,BackgroundColor3=Color3.fromRGB(29,23,36),BorderSizePixel=0,Selectable=true},nav) round(b,17)
    local border=make("UIStroke",{Color=purple,Transparency=.8},b)
    buttons[name]={button=b,border=border}
    listen(b.Activated,function()
        active=name
        for key,p in pairs(pages) do p.Visible=key==active end
        for key,item in pairs(buttons) do
            Tween:Create(item.button,TweenInfo.new(.15),{BackgroundColor3=key==active and Color3.fromRGB(89,48,124) or Color3.fromRGB(29,23,36),TextColor3=key==active and white or muted}):Play()
            item.border.Transparency=key==active and .2 or .8
        end
        filter()
    end)
    return left,right
end
local sequence=0
local function row(column,name,height)
    sequence=sequence+1
    local card=make("Frame",{Size=UDim2.new(1,-4,0,height or 46),BackgroundColor3=Color3.fromRGB(36,29,44),BorderSizePixel=0,LayoutOrder=sequence},column) round(card,12)
    local outline=make("UIStroke",{Color=purple,Transparency=.9},card)
    listen(card.MouseEnter,function() Tween:Create(outline,TweenInfo.new(.15),{Transparency=.45}):Play() end)
    listen(card.MouseLeave,function() Tween:Create(outline,TweenInfo.new(.15),{Transparency=.9}):Play() end)
    table.insert(rows,{name=name,object=card})
    return card
end
local function section(column,name)
    local h=row(column,name,24) h.BackgroundTransparency=1
    for _,o in ipairs(h:GetChildren()) do if o:IsA("UIStroke") then o:Destroy() end end
    text(h,name,UDim2.fromOffset(8,0),UDim2.new(1,-16,1,0),11,muted)
end
local function toggle(column,name,default,callback)
    local card=row(column,name)
    text(card,name,UDim2.fromOffset(12,0),UDim2.new(1,-82,1,0),12)
    local track=make("TextButton",{Position=UDim2.new(1,-66,.5,-12),Size=UDim2.fromOffset(50,24),Text="",BackgroundColor3=Color3.fromRGB(66,58,74),BorderSizePixel=0,Selectable=true},card) round(track,12)
    local knob=make("Frame",{Position=UDim2.fromOffset(3,3),Size=UDim2.fromOffset(18,18),BackgroundColor3=white,BorderSizePixel=0},track) round(knob,9)
    local value=default==true
    local function render()
        Tween:Create(track,TweenInfo.new(.16),{BackgroundColor3=value and purple or Color3.fromRGB(66,58,74)}):Play()
        Tween:Create(knob,TweenInfo.new(.16),{Position=UDim2.fromOffset(value and 29 or 3,3)}):Play()
    end
    render()
    listen(track.Activated,function() value=not value render() note(name..": "..(value and "ON" or "OFF")) if callback then callback(value) end end)
end
local function slider(column,name,min,max,default,suffix)
    local card=row(column,name,76)
    text(card,name,UDim2.fromOffset(12,9),UDim2.new(1,-92,0,22),12)
    local val=text(card,"",UDim2.new(1,-80,0,9),UDim2.fromOffset(68,22),11,muted) val.TextXAlignment=Enum.TextXAlignment.Right
    local track=make("TextButton",{Position=UDim2.fromOffset(13,47),Size=UDim2.new(1,-26,0,9),BackgroundColor3=Color3.fromRGB(63,53,73),BorderSizePixel=0,Text="",Active=true},card) round(track,5)
    local fill=make("Frame",{Size=UDim2.fromScale(0,1),BackgroundColor3=purple,BorderSizePixel=0},track) round(fill,5)
    make("UIGradient",{Color=ColorSequence.new(Color3.fromRGB(96,47,161),bright)},fill)
    local knob=make("Frame",{Size=UDim2.fromOffset(26,18),AnchorPoint=Vector2.new(.5,.5),Position=UDim2.fromScale(0,.5),BackgroundColor3=white,BorderSizePixel=0},track) round(knob,9)
    local dragging=false
    local function set(value)
        value=math.clamp(math.floor(value+.5),min,max)
        local a=(value-min)/(max-min)
        fill.Size=UDim2.fromScale(a,1) knob.Position=UDim2.fromScale(a,.5) val.Text=tostring(value)..(suffix or "")
    end
    local function update(input) local width=track.AbsoluteSize.X if width>0 then set(min+(max-min)*math.clamp((input.Position.X-track.AbsolutePosition.X)/width,0,1)) end end
    set(default)
    listen(track.InputBegan,function(input) if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then dragging=true update(input) end end)
    listen(UIS.InputChanged,function(input) if dragging and (input.UserInputType==Enum.UserInputType.MouseMovement or input.UserInputType==Enum.UserInputType.Touch) then update(input) end end)
    listen(UIS.InputEnded,function(input) if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then dragging=false end end)
end
local function button(column,name,callback)
    local card=row(column,name)
    local b=make("TextButton",{Size=UDim2.fromScale(1,1),Text=name,Font=Enum.Font.GothamMedium,TextSize=12,TextColor3=bright,BackgroundTransparency=1,Selectable=true},card)
    listen(b.Activated,callback or function() note(name.." selected (UI example).") end)
end
local a,b=tab("Main")
section(a,"Movement") toggle(a,"Speed override",false) slider(a,"Walk speed",0,150,32)
toggle(a,"Jump override",false) slider(a,"Jump power",0,200,75)
section(b,"Camera") toggle(b,"Custom field of view",false) slider(b,"Field of view",30,120,80," deg")
toggle(b,"Camera stabilization",false) button(b,"Reset movement settings")
a,b=tab("Visuals")
section(a,"World lighting") toggle(a,"Fullbright",false) toggle(a,"Reduce shadows",false) toggle(a,"Reduce particles",false)
section(b,"Interface") toggle(b,"Show FPS",true,function(value) fps.Visible=value end) toggle(b,"Accent outline",true,function(value) for _,o in ipairs(main:GetChildren()) do if o:IsA("UIStroke") then o.Enabled=value end end end)
slider(b,"Interface scale",65,100,100,"%")
a,b=tab("World")
section(a,"Saved locations") button(a,"Save current location") button(a,"Teleport to saved location") button(a,"Clear saved location")
section(b,"Navigation") toggle(b,"Noclip",false) button(b,"Copy coordinates") button(b,"Server information",function() note("Place: "..tostring(game.PlaceId).." | Players: "..#Players:GetPlayers()) end)
a,b=tab("Player")
section(a,"Player tools") button(a,"Character information",function() note("Player: "..Players.LocalPlayer.DisplayName) end) button(a,"Respawn character")
section(b,"Preferences") toggle(b,"Remember settings",false) button(b,"Reset player settings")
a,b=tab("Settings")
section(a,"Mystic Wolf") toggle(a,"Dim background",false) button(a,"Purple theme",function() note("Mystic purple theme selected.") end)
section(b,"Window") button(b,"Minimize menu",function() show(false) end) button(b,"Close menu",cleanup)
button(b,"About Mystic Mods",function() note("Mystic Mods / Mystic Wolf. UI showcase; attach feature callbacks to your game.") end)
pages.Main.Visible=true buttons.Main.button.BackgroundColor3=Color3.fromRGB(89,48,124) buttons.Main.button.TextColor3=white buttons.Main.border.Transparency=.2
listen(search:GetPropertyChangedSignal("Text"),filter)
local dragging=false local start,position
listen(header.InputBegan,function(input) if input.UserInputType==Enum.UserInputType.MouseButton1 then dragging=true start=input.Position position=main.Position end end)
listen(UIS.InputChanged,function(input)
    if dragging and input.UserInputType==Enum.UserInputType.MouseMovement then
        local delta=input.Position-start
        local v=workspace.CurrentCamera.ViewportSize
        local half=Vector2.new(680,570)*scale.Scale/2
        local center=Vector2.new(position.X.Scale*v.X+position.X.Offset,position.Y.Scale*v.Y+position.Y.Offset)+Vector2.new(delta.X,delta.Y)
        main.Position=UDim2.fromOffset(math.clamp(center.X,half.X,v.X-half.X),math.clamp(center.Y,half.Y,v.Y-half.Y))
    end
end)
listen(UIS.InputEnded,function(input) if input.UserInputType==Enum.UserInputType.MouseButton1 then dragging=false end end)
listen(UIS.InputBegan,function(input,processed) if not processed and not UIS:GetFocusedTextBox() and input.KeyCode==Enum.KeyCode.RightShift then show(not main.Visible) end end)
local elapsed,frames=0,0
listen(Run.RenderStepped,function(dt)
    local camera=workspace.CurrentCamera
    if camera then scale.Scale=math.max(.1,math.min(1,(camera.ViewportSize.X-30)/680,(camera.ViewportSize.Y-30)/570)) end
    elapsed=elapsed+dt frames=frames+1
    if elapsed>=.5 then fps.Text=string.format("FPS %d",math.floor(frames/elapsed+.5)) elapsed=0 frames=0 end
end)
